export type NcertSubject = 'Polity' | 'History' | 'Geography' | 'Economics' | 'General Science';

export interface NcertQuestion {
  id: string;
  questionText: string;
  options: string[];
  correctOption: number;
  explanation: string;
  /** Written from textbook concepts, never copied from end-of-chapter exercises. */
  type?: 'concept-check' | 'line-detail' | 'application';
}

export interface NcertChapter {
  id: string;
  order: number;
  title: string;
  book: string;
  /** Locator for the official source used to author this revision unit. */
  sourceFocus?: string;
  notes: string[];
  questions: NcertQuestion[];
}

export interface NcertTrack {
  id: string;
  subject: NcertSubject;
  title: string;
  description: string;
  sourceUrl: string;
  chapters: NcertChapter[];
}

